head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// Footer 의 합계 표시 셀 텍스트를 읽어 출력
scwin.printFooterSum = function (strPrefix) {
    var objCell = document.querySelector("td[id$='_fcol2']");
    scwin.setReturnValue(strPrefix + " Footer 합계(sum) 표시값 : " + (objCell ? objCell.textContent.trim() : "(없음)"));
};

scwin.btn_checkSum_onclick = function (e) {
    scwin.printFooterSum("[현재]");
};

// 추가 후 삭제 : insertRow 로 1,000 을 추가(상태 C) 한 뒤 같은 Row 를 삭제하여 상태 V 로 만든다
scwin.btn_makeV_onclick = function (e) {
    var objDlt = $p.getComponentById("dlt_bind");

    objDlt.insertRow(2);
    objDlt.setCellData(2, "name", "NewRow");
    objDlt.setCellData(2, "amount", 1000);
    var strStatusC = objDlt.getRowStatus(2);

    objDlt.deleteRow(2);
    scwin.setReturnValue("=====1,000 짜리 Row 추가(상태 " + strStatusC + ") 후 삭제 → Row 상태값 : " + objDlt.getRowStatus(2) + "=====");

    // Footer 재계산이 비동기로 처리되므로 지연 후 읽는다
    setTimeout(function () { scwin.printFooterSum("[추가 후 삭제 적용 후]"); }, 400);
};
